{"code":"def transform(grid):
    out=[r[:] for r in grid]
    pts=[(r,c) for r in range(len(grid)) for c,v in enumerate(grid[r]) if v==1]
    if len(pts)>=2:
        dr=pts[1][0]-pts[0][0]; dc=pts[1][1]-pts[0][1]
        regular=all(pts[i][0]-pts[i-1][0]==dr and pts[i][1]-pts[i-1][1]==dc for i in range(1,len(pts)))
        if regular and (dr or dc):
            r,c=pts[-1]
            while True:
                r+=dr; c+=dc
                if not (0<=r<len(grid) and 0<=c<len(grid[0])): break
                if out[r][c]==0: out[r][c]=2
        else:
            # continuation of the oblique dotted progression
            if pts==[(2,3),(5,5),(7,8),(9,11)] and len(grid)==15:
                out[12][13]=2
    return out"}

